/* Fictional practice cases; background references are not endorsements or legal approvals. */
(function(r){const d={"version":1,"checked":"2026-10-25","sources":[{"id":"ico-principles","title":"ICO: data protection principles","url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/data-protection-principles/a-guide-to-the-data-protection-principles/","scope":"UK reference: purpose, proportionate data, accuracy, security and accountability. Guidance is under review; consult current local requirements."},{"id":"ico-investigators","title":"ICO: private-investigator code announcement","url":"https://ico.org.uk/about-the-ico/media-centre/news-and-blogs/2024/11/new-data-protection-code-of-conduct-launched-for-uk-private-investigators/","scope":"UK reference: investigation-sector data protection. Does not establish licensing or lawful authority for a particular case."},{"id":"ut-records","title":"University of Tennessee Extension: Honey Bee Inspections and Recordkeeping, W1151","url":"https://solutions.tennessee.edu/publication/W1151/","scope":"US extension reference: colony observations and useful inspection records."},{"id":"arkansas-bees","title":"University of Arkansas Extension: beekeeping publications","url":"https://www.uaex.uada.edu/farm-ranch/special-programs/beekeeping/beepubs.aspx","scope":"Arkansas extension reference and further training: equipment, biology, seasonal management and bee health."},{"id":"apha-health","title":"APHA: inspections, bee health and medicine records","url":"https://www.gov.uk/guidance/honey-bees-inspection-to-control-notifiable-pests-and-diseases","scope":"England and Wales reference. Other places have their own authorities and reporting requirements."},{"id":"bbka-start","title":"British Beekeepers Association: getting started","url":"https://www.bbka.org.uk/becoming-a-beekeeper","scope":"UK association reference: practical tuition, local association support and mentoring."}],"assignments":[{"id":"investigator-01","track":"investigator","number":1,"title":"Open a properly scoped case","source":"Fictional request PI-101: the Welcome House asks Nell to reconcile its missing blanket delivery using its own dispatch papers. Approved scope: delivery records only. No household background checks are authorised.","fields":[{"label":"Case reference","answer":"PI-101","reason":"Copy the request reference, including its number."},{"label":"Approved scope","answer":"delivery records only","reason":"Use the supplied scope; curiosity does not expand it."},{"label":"Excluded work","answer":"household background checks","reason":"The request expressly excludes this work."}],"method":["Read who requested the work and why.","Locate the approved records and exclusions.","Write the reference and scope before accepting any documents.","Ask the requester to clarify any new request outside that scope."],"example":"Example: PI-090 concerns a lost parcel; a written scope of parcel records excludes unrelated tenant enquiries.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-02","track":"investigator","number":2,"title":"Record authority before collecting records","source":"PI-102: the store offers its own stock ledger for an agreed reconciliation. Authority note AUTH-12 covers stock ledger S-4. A separate personnel folder is outside the written request. Exercise policy: hold excluded documents for authorised review without reading them.","fields":[{"label":"Authority reference","answer":"AUTH-12","reason":"Use the recorded authority note."},{"label":"Permitted record","answer":"S-4","reason":"Only the named stock ledger is in scope."},{"label":"Personnel-folder action","answer":"hold for authorised review","reason":"Do not inspect an excluded file."}],"method":["Match the authority note to the exact ledger.","List the covered record separately from excluded material.","Record the review hold.","Before real work, confirm jurisdiction, lawful basis and professional requirements; this exercise is not a legal approval."],"example":"Example: AUTH-09 names invoice I-8; a payroll folder is set aside for authorised review.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-03","track":"investigator","number":3,"title":"Check for a conflict of interest","source":"PI-103: Nell previously prepared the disputed invoice for Case C-8. Fictional office policy requires disclosure to the supervisor and reassignment when the investigator created the disputed record.","fields":[{"label":"Conflicting case","answer":"C-8","reason":"The earlier case connects Nell to the disputed evidence."},{"label":"Notify","answer":"supervisor","reason":"Follow this office policy."},{"label":"Disposition","answer":"reassignment","reason":"Do not investigate your own disputed work under this scenario."}],"method":["Compare the assignment with the prior-work register.","Record the factual connection without defending the invoice.","Send the disclosure to the named supervisor.","Mark the case for reassignment, not completed investigation."],"example":"Example: an investigator who signed disputed delivery D-2 discloses that connection before another worker takes the case.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-04","track":"investigator","number":4,"title":"Prepare a neutral interview plan","source":"PI-104: an adult volunteer agrees to discuss a delayed cart. Exercise question: What did you directly see? The interview is at the public meeting room at 10:00. Avoid the suggested question Why did the driver steal it?","fields":[{"label":"Meeting time","answer":"10:00","reason":"Use the agreed appointment."},{"label":"Meeting place","answer":"public meeting room","reason":"Use the agreed public room."},{"label":"Opening question","answer":"What did you directly see?","reason":"Ask for observation without assuming a crime."}],"method":["Read the appointment and purpose.","Prepare an open question before follow-up details.","Separate what someone saw from what they heard.","Do not introduce an accusation as an established fact."],"example":"Example: ask What happened at the desk? rather than Why did the clerk lie?","refs":["ico-principles","ico-investigators"]},{"id":"investigator-05","track":"investigator","number":5,"title":"Log voluntary interview preferences","source":"PI-105: volunteer A chooses written notes, declines audio recording, and asks to pause at any time. Exercise policy honours all three choices; this is not a statement that consent alone makes every real investigation lawful.","fields":[{"label":"Record format","answer":"written notes","reason":"This is the chosen format."},{"label":"Audio permission","answer":"declined","reason":"No recording is agreed."},{"label":"Pause arrangement","answer":"at any time","reason":"Preserve the volunteer’s stated preference."}],"method":["Read preferences back before starting.","Choose written notes rather than recording.","Explain the agreed pause option.","Record the preferences without collecting unrelated personal details."],"example":"Example: volunteer B chooses a written statement and no photographs; prepare that format.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-06","track":"investigator","number":6,"title":"Separate observation from hearsay","source":"PI-106: Note N1 says I saw the blue cart at 09:10. Note N2 says Someone told me it left at 09:30. Neither note identifies a thief.","fields":[{"label":"Direct-observation note","answer":"N1","reason":"The speaker describes seeing the cart."},{"label":"Second-hand note","answer":"N2","reason":"The speaker reports what someone else said."},{"label":"Identity of thief","answer":"not established","reason":"Neither source supplies that conclusion."}],"method":["Read the exact wording of each note.","Label the direct observation and the second-hand account.","Keep both attributed to their sources.","Leave the unproved identity unresolved."],"example":"Example: I heard a bell is an observation; Jo told me the bell rang is a second-hand account.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-07","track":"investigator","number":7,"title":"Build a sourced timeline","source":"PI-107: gate log G records arrival at 08:40; receipt R records unloading at 09:05; exit log X records departure at 09:20. All three supplied times use the same local date and clock.","fields":[{"label":"First event reference","answer":"G","reason":"08:40 is earliest."},{"label":"Unloading time","answer":"09:05","reason":"Use receipt R, not the departure time."},{"label":"Minutes from arrival to departure","answer":"40","reason":"08:40 to 09:20 is 40 minutes."}],"method":["Confirm a common date and time basis.","Order events by their source times.","Calculate elapsed time without adding unsupported stops.","Keep each event tied to its reference."],"example":"Example: arrival 11:10 and exit 11:35 give a 25-minute interval, not proof of every activity in between.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-08","track":"investigator","number":8,"title":"Resolve a timestamp uncertainty","source":"PI-108: camera note C says 14:00 but its clock is unverified. Signed receipt R says 14:07. Exercise report policy retains original times and flags the camera-clock uncertainty instead of silently adjusting it.","fields":[{"label":"Unverified clock source","answer":"C","reason":"The camera clock has not been checked."},{"label":"Receipt time","answer":"14:07","reason":"Preserve the signed receipt time."},{"label":"Camera time action","answer":"retain and flag uncertainty","reason":"Do not invent a seven-minute correction."}],"method":["Record both original timestamps.","Identify which clock is unverified.","Add the uncertainty to the timeline.","Request clock verification before claiming an exact sequence."],"example":"Example: a device reads 12:01 and a docket reads 12:04; record both until their clocks can be compared.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-09","track":"investigator","number":9,"title":"Create an evidence inventory","source":"PI-109: supplied items are envelope E-1, receipt E-2 and photograph E-3. Three items arrive sealed in transfer package T-9. This is a fictional desk exercise, not evidence seizure.","fields":[{"label":"Transfer package","answer":"T-9","reason":"Keep the package reference."},{"label":"Item count","answer":"3","reason":"Count the three listed items."},{"label":"Receipt item ID","answer":"E-2","reason":"Match the receipt to its own identifier."}],"method":["Compare the package list with the visible item labels.","Count without altering the supplied contents.","Give each item its own inventory row.","Flag any missing item instead of inventing a replacement."],"example":"Example: a package with F-1 and F-2 has two listed items; a missing F-2 is a discrepancy.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-10","track":"investigator","number":10,"title":"Record a documented handover","source":"PI-110: exercise item E-8 passes from Desk A to Desk B at 13:15 under transfer T-10. The receiving clerk confirms the seal is intact.","fields":[{"label":"Transfer reference","answer":"T-10","reason":"Use the transfer reference, not the item number."},{"label":"Receiving desk","answer":"Desk B","reason":"Record who received the item."},{"label":"Seal condition","answer":"intact","reason":"Use the documented condition."}],"method":["Identify the item before handover.","Record sender, receiver, time and transfer reference.","Compare the stated condition before accepting it.","Keep the transfer with the item history; do not claim court admissibility from this exercise."],"example":"Example: F-3 moves from Shelf 1 to Review Desk at 15:20 with its condition recorded.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-11","track":"investigator","number":11,"title":"Protect the original document","source":"PI-111: original file O-7 is read-only. Working copy W-7 is approved for annotations. Exercise policy says preserve O-7 unchanged and label W-7 as a working copy.","fields":[{"label":"Original ID","answer":"O-7","reason":"The original must remain identifiable."},{"label":"Annotate which file","answer":"W-7","reason":"Use only the approved working copy."},{"label":"Original action","answer":"preserve unchanged","reason":"Do not overwrite the source."}],"method":["Identify original and working-copy labels.","Record where the original is held.","Put annotations on the working copy only.","Keep annotations distinguishable from source content."],"example":"Example: mark a copy of invoice I-3 for review while preserving the supplied original.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-12","track":"investigator","number":12,"title":"Verify a document claim","source":"PI-112: index entry A cites receipt R-22 for 12 blankets. Receipt R-22 actually states 10 blankets. The index is a secondary summary; the supplied receipt is the source being checked.","fields":[{"label":"Source reference","answer":"R-22","reason":"Identify the document you inspected."},{"label":"Verified blanket count","answer":"10","reason":"Read the source quantity."},{"label":"Index discrepancy","answer":"2","reason":"12 minus 10 equals 2."}],"method":["Find the source named by the index.","Compare the original quantity with the summary.","Calculate the difference.","Report the mismatch without guessing why it happened."],"example":"Example: a summary says 9 crates and its docket says 8; flag a difference of 1.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-13","track":"investigator","number":13,"title":"Correct an error transparently","source":"PI-113: saved entry V1 says 16:40; source S-6 says 16:04. Exercise policy requires corrected entry V2, source S-6 and preservation of the prior version.","fields":[{"label":"Correct time","answer":"16:04","reason":"Copy the source exactly."},{"label":"Correction source","answer":"S-6","reason":"Record the correction’s basis."},{"label":"Prior version action","answer":"preserve V1","reason":"Keep the audit trail."}],"method":["Compare V1 against the named source.","Write the corrected value as a new version.","Record the reason and source.","Retain the earlier version rather than erasing its existence."],"example":"Example: change a transposed date in V2 and retain the marked V1 for the audit history.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-14","track":"investigator","number":14,"title":"Maintain an enquiry log","source":"PI-114: request Q-4 sent to the Gazette archive on 4 June is unanswered. Fictional follow-up date is 11 June. Status choices are pending or received; no response has arrived.","fields":[{"label":"Request ID","answer":"Q-4","reason":"Keep the enquiry reference."},{"label":"Status","answer":"pending","reason":"A sent request is not a received answer."},{"label":"Follow-up date","answer":"11 June","reason":"This is the supplied case date, not a game deadline."}],"method":["Record recipient and sent date.","Check whether any response exists.","Use pending while unanswered.","Record the planned follow-up without inventing a reply."],"example":"Example: an archive request sent on 2 May remains pending until a response is logged.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-15","track":"investigator","number":15,"title":"Minimise unrelated personal data","source":"PI-115: the agreed delivery reconciliation needs delivery reference D-6, quantity 8 and delivery date. An unrelated medical note is attached. Exercise policy excludes that medical note and escalates its handling to the data lead.","fields":[{"label":"Relevant reference","answer":"D-6","reason":"Use only the delivery reference needed here."},{"label":"Relevant quantity","answer":"8","reason":"This relates to the agreed purpose."},{"label":"Unrelated note action","answer":"refer to data lead","reason":"Do not copy it into the case report."}],"method":["Compare each supplied detail with the case purpose.","Record only the relevant delivery facts.","Keep the unrelated note out of the report.","Ask the data lead how to handle the unwanted attachment."],"example":"Example: reconcile a parcel using its reference and count, not the recipient’s unrelated health history.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-16","track":"investigator","number":16,"title":"Separate an allegation from a finding","source":"PI-116: a caller alleges theft. The only checked source is an unsigned draft order; no delivery or stock count has been verified. Exercise reporting terms: allegation for the caller’s claim, unverified for the draft, no finding yet for theft.","fields":[{"label":"Caller claim label","answer":"allegation","reason":"Attribute the claim rather than endorse it."},{"label":"Draft status","answer":"unverified","reason":"A draft alone does not verify delivery."},{"label":"Theft conclusion","answer":"no finding yet","reason":"The available material cannot establish theft."}],"method":["Attribute the allegation to its caller.","Describe exactly which document was reviewed.","State the missing checks.","Avoid accusing a person without supported findings."],"example":"Example: a complaint about a missing box is recorded as a complaint while delivery evidence is checked.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-17","track":"investigator","number":17,"title":"Compare two independent accounts","source":"PI-117: witness A directly reports a green cart at 12:10. Witness B independently reports a green cart at 12:10. Neither identifies the driver. Agreement concerns cart colour and time only.","fields":[{"label":"Agreed colour","answer":"green","reason":"Both independent accounts agree on colour."},{"label":"Agreed time","answer":"12:10","reason":"Both report this time."},{"label":"Driver identity","answer":"not established","reason":"Do not extend agreement beyond the accounts."}],"method":["Compare like details separately.","Record agreement on colour and time.","Note the independence stated in the source.","Keep the driver’s identity unresolved."],"example":"Example: two accounts agree a bell sounded at noon; neither establishes who rang it.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-18","track":"investigator","number":18,"title":"Recognise duplicate sources","source":"PI-118: article B copies article A. Article C also quotes A. Exercise source map names A as the single original account; three publications are not three independent witnesses.","fields":[{"label":"Original account","answer":"A","reason":"Trace the shared origin."},{"label":"Publication count","answer":"3","reason":"A, B and C are three publications."},{"label":"Independent original accounts","answer":"1","reason":"All three trace back to A."}],"method":["Read each publication’s attribution.","Draw the source links back to A.","Count original accounts separately from copies.","Describe corroboration honestly."],"example":"Example: four newsletters repeating one interview still contain one original interview.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-19","track":"investigator","number":19,"title":"Request lawful archive access","source":"PI-119: archive catalogue ARC-3 lists a public bridge plan. Access route is the archive request desk. A staff-only cabinet is not included. Exercise policy forbids bypassing restricted access.","fields":[{"label":"Catalogue reference","answer":"ARC-3","reason":"Use the listed plan reference."},{"label":"Access route","answer":"archive request desk","reason":"Use the supplied authorised route."},{"label":"Staff-only cabinet action","answer":"do not access","reason":"The case does not grant access."}],"method":["Find the catalogue entry.","Request the listed item at the proper desk.","Record access conditions.","If refused, log the refusal and request review rather than bypassing it."],"example":"Example: request a published minute book through its catalogue rather than entering a locked office.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-20","track":"investigator","number":20,"title":"Redact an exercise disclosure copy","source":"PI-120: release approval REL-2 permits case summary CS-1 but excludes a private telephone number. Working policy: redact the disclosure copy, retain the restricted original and send only to the approved recipient Desk C.","fields":[{"label":"Approval reference","answer":"REL-2","reason":"Match the release approval."},{"label":"Approved recipient","answer":"Desk C","reason":"Do not widen distribution."},{"label":"Exclude from copy","answer":"private telephone number","reason":"Apply the stated redaction."}],"method":["Compare the requested copy with the release approval.","Remove the excluded detail from the disclosure copy.","Check that the excluded text is not visible in the copy.","Preserve the restricted original and log the approved release."],"example":"Example: a public summary omits a private contact detail while the restricted source remains protected.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-21","track":"investigator","number":21,"title":"Assess an unsupported conclusion","source":"PI-121: a missing parcel has no signed receipt. The store was busy. A draft says The clerk deliberately hid it. Supplied evidence supports delivery status unknown, not intent.","fields":[{"label":"Delivery status","answer":"unknown","reason":"No signed receipt establishes delivery."},{"label":"Intent status","answer":"not established","reason":"A busy store does not prove intent."},{"label":"Draft action","answer":"remove unsupported conclusion","reason":"Keep the report within the evidence."}],"method":["Identify the conclusion being claimed.","List what the sources actually establish.","Remove the unsupported statement.","Write the remaining uncertainty plainly."],"example":"Example: a late reply does not itself prove dishonesty; report the late reply and missing information.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-22","track":"investigator","number":22,"title":"Prepare a clear status update","source":"PI-122: checked records 6 of 10; outstanding 4; next action compare dispatch log. Exercise update must distinguish completed checks from planned work.","fields":[{"label":"Checked records","answer":"6","reason":"Use the completed count."},{"label":"Outstanding records","answer":"4","reason":"10 minus 6 equals 4."},{"label":"Next action","answer":"compare dispatch log","reason":"This is planned, not already done."}],"method":["Count completed checks from the log.","Calculate the remainder.","State the next action in future terms.","Avoid promising a result before reviewing the log."],"example":"Example: 3 of 7 files checked leaves 4; the update says review continues, not case solved.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-23","track":"investigator","number":23,"title":"Estimate work transparently","source":"PI-123: exercise estimate allows 3 hours at £20 per hour plus £8 approved copying. No other charges are authorised. These are fictional practice rates, not recommended market prices.","fields":[{"label":"Labour amount","answer":"60","reason":"3 multiplied by 20 equals 60."},{"label":"Approved copying","answer":"8","reason":"Use only the authorised extra."},{"label":"Estimated total","answer":"68","reason":"60 plus 8 equals 68."}],"method":["Separate hours, rate and approved extras.","Multiply hours by the rate.","Add the approved copying cost.","Label the amount an estimate, not payment received."],"example":"Example: 2 hours at £15 plus £5 copying gives an estimate of £35.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-24","track":"investigator","number":24,"title":"Reconcile an investigation invoice","source":"PI-124: time log shows 2 hours at £25; approved travel £6; draft invoice £66. Correct total is labour plus approved travel.","fields":[{"label":"Labour amount","answer":"50","reason":"2 multiplied by 25 equals 50."},{"label":"Correct total","answer":"56","reason":"50 plus 6 equals 56."},{"label":"Overstatement","answer":"10","reason":"66 minus 56 equals 10."}],"method":["Match hours to the time log.","Calculate labour and approved extras.","Compare the result with the draft.","Return the discrepancy for correction without marking it paid."],"example":"Example: £40 labour plus £4 approved copies totals £44, regardless of a mistaken £49 draft.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-25","track":"investigator","number":25,"title":"Prepare a neutral interview summary","source":"PI-125: volunteer D says I saw two boxes, but I did not see inside them. Note reference INT-5. Do not rewrite this as two boxes of honey.","fields":[{"label":"Interview reference","answer":"INT-5","reason":"Keep the summary attributable."},{"label":"Boxes observed","answer":"2","reason":"This is the directly reported count."},{"label":"Contents","answer":"not observed","reason":"The witness expressly did not see inside."}],"method":["Read the statement completely.","Summarise its observation without adding contents.","Keep the limitation beside the finding.","Offer the summary for correction under the exercise procedure."],"example":"Example: saw a sealed envelope does not establish what the envelope contained.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-26","track":"investigator","number":26,"title":"Plan a safe voluntary meeting","source":"PI-126: interview appointment uses the public office at 11:00. Exercise safety plan requires a colleague check-in and leaving if threatened. No lone private-location meeting is approved.","fields":[{"label":"Approved venue","answer":"public office","reason":"Use the agreed public location."},{"label":"Check-in contact","answer":"colleague","reason":"Follow the safety plan."},{"label":"If threatened","answer":"leave and seek help","reason":"Do not continue an unsafe interview."}],"method":["Confirm location and check-in plan.","Keep the meeting voluntary and within scope.","Record any change of plan before proceeding.","Stop rather than escalating a threatening encounter."],"example":"Example: move an unapproved isolated appointment back to the agreed public office.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-27","track":"investigator","number":27,"title":"Handle an urgent welfare concern","source":"PI-127: a fictional caller reports an immediate danger to a child. Exercise action card says contact emergency services, give the known location and avoid a personal rescue investigation. No emergency number is supplied because location-specific services must be used in real life.","fields":[{"label":"First service","answer":"emergency services","reason":"An urgent danger is not a routine case queue."},{"label":"Information to give","answer":"known location","reason":"Pass known facts clearly."},{"label":"Routine enquiry status","answer":"pause","reason":"Do not continue ordinary research instead of escalating."}],"method":["Identify the immediate-danger statement.","Follow the exercise emergency escalation card.","Pass known facts without inventing details.","Record the handover; do not attempt an untrained rescue."],"example":"Example: immediate danger is escalated promptly while a normal missing-invoice enquiry can wait.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-28","track":"investigator","number":28,"title":"Review a retention instruction","source":"PI-128: fictional schedule calls for review on 30 June. A hold H-2 is active. Exercise policy says preserve held records and ask the records lead before disposal; the date is not a legal retention period.","fields":[{"label":"Review date","answer":"30 June","reason":"Use the supplied exercise schedule."},{"label":"Active hold","answer":"H-2","reason":"Record why routine disposal cannot proceed."},{"label":"Disposition","answer":"preserve pending review","reason":"Do not erase a held file."}],"method":["Check the schedule and any hold.","Record the review date separately from disposal approval.","Keep the held record protected.","Ask the records lead to resolve the hold before any disposal."],"example":"Example: a scheduled review on 1 July does not override an active preservation hold.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-29","track":"investigator","number":29,"title":"Write a defensible final finding","source":"PI-129: dispatch D-1 records 8 blankets; receipt R-1 records 6; later receipt R-2 records 2. All refer to the same order. The evidence supports complete quantity over two deliveries, not a theft finding.","fields":[{"label":"Total received","answer":"8","reason":"6 plus 2 equals 8."},{"label":"Number of deliveries","answer":"2","reason":"R-1 and R-2 are separate receipts."},{"label":"Supported finding","answer":"complete quantity over two deliveries","reason":"Limit the conclusion to the matched records."}],"method":["Match all references to the same order.","Add the two receipt counts.","Compare the total with dispatch.","Write the supported finding and cite both receipts."],"example":"Example: an order for 5 arrives as 3 then 2; explain the split delivery rather than declaring a loss.","refs":["ico-principles","ico-investigators"]},{"id":"investigator-30","track":"investigator","number":30,"title":"Close and hand over a case","source":"PI-130: final report FR-3 is approved for Desk D. Inventory has 5 listed items and all 5 are accounted for. Exercise closure status is closed after the recorded handover, not before.","fields":[{"label":"Report ID","answer":"FR-3","reason":"Identify the approved final report."},{"label":"Handover recipient","answer":"Desk D","reason":"Use the authorised recipient."},{"label":"Unaccounted items","answer":"0","reason":"5 listed minus 5 accounted for equals zero."}],"method":["Check report approval and recipient.","Reconcile the inventory.","Record the actual handover and unresolved limitations.","Only then mark the exercise case closed; retain records according to its approved schedule."],"example":"Example: report FR-1 and 3 accounted items go to the approved desk before closure is logged.","refs":["ico-principles","ico-investigators"]},{"id":"beekeeper-01","track":"beekeeper","number":1,"title":"Create an apiary register","source":"Training apiary A-1 contains colonies H-01, H-02 and H-03. The site reference is Meadow East. These are fictional colonies; no live hive is opened in this exercise.","fields":[{"label":"Apiary ID","answer":"A-1","reason":"Use the site identifier."},{"label":"Site name","answer":"Meadow East","reason":"Copy the recorded site."},{"label":"Colony count","answer":"3","reason":"Count the three distinct colony IDs."}],"method":["Identify the apiary before entering colony records.","List each colony separately.","Count unique IDs rather than boxes.","Keep the register available for later inspection records."],"example":"Example: apiary B-2 with K-1 and K-2 contains two recorded colonies.","refs":["ut-records","arkansas-bees"]},{"id":"beekeeper-02","track":"beekeeper","number":2,"title":"Check the equipment inventory","source":"Training inventory lists 4 veils; 1 has a torn mesh and is marked out of service. The exercise requires sound protective equipment before any mentored visit.","fields":[{"label":"Total veils","answer":"4","reason":"Count all recorded veils."},{"label":"Out of service","answer":"1","reason":"Exclude the torn item from usable stock."},{"label":"Usable veils","answer":"3","reason":"4 minus 1 equals 3."}],"method":["Read the condition label for every item.","Separate damaged equipment from usable equipment.","Calculate the usable quantity.","Record the replacement request; do not treat a torn veil as protection."],"example":"Example: 5 suits with 2 faulty zips leave 3 serviceable suits.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-03","track":"beekeeper","number":3,"title":"Review a proposed apiary site","source":"Exercise site card: Pond Edge has an unobstructed public path through the proposed hive entrance area. Approved plan is hold for mentor site review; no hive placement has been authorised.","fields":[{"label":"Site","answer":"Pond Edge","reason":"Use the proposed site name."},{"label":"Concern","answer":"public path","reason":"Identify the conflicting route."},{"label":"Decision","answer":"hold for mentor site review","reason":"Do not approve a site from incomplete information."}],"method":["Mark the proposed hive position on the supplied plan.","Identify the shared route and unresolved exposure.","Record the hold rather than moving hives.","Arrange a local mentor’s site assessment."],"example":"Example: a gate beside a proposed entrance requires site review before bees are installed.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-04","track":"beekeeper","number":4,"title":"Plan a weather-aware visit","source":"Training weather card reports cold rain and strong wind. The mentor’s exercise instruction is postpone opening; record external observations only. This is a supplied scenario decision, not a universal temperature rule.","fields":[{"label":"Weather","answer":"cold rain and strong wind","reason":"Copy the observed conditions."},{"label":"Opening decision","answer":"postpone","reason":"Follow the mentor’s instruction."},{"label":"Allowed observation","answer":"external only","reason":"Do not log an internal inspection."}],"method":["Read the current conditions and mentor instruction.","Record why opening is postponed.","Keep the visit record limited to external observations.","Arrange a later mentored review rather than inventing brood findings."],"example":"Example: a cancelled internal visit still has a truthful weather and external-observation record.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-05","track":"beekeeper","number":5,"title":"Prepare a mentored inspection checklist","source":"Visit V-5 is assigned to H-02. Mentor M-1 must be present. Checklist contains protective clothing, inspection record and approved equipment. No independent opening is authorised.","fields":[{"label":"Visit reference","answer":"V-5","reason":"Use the planned visit ID."},{"label":"Colony","answer":"H-02","reason":"Match the intended colony."},{"label":"Required mentor","answer":"M-1","reason":"The practical visit requires this mentor."}],"method":["Match visit and colony IDs.","Check clothing and equipment against the supplied list.","Prepare a blank inspection record.","Wait for the mentor before handling a colony."],"example":"Example: visit V-2 to H-08 is not a completed inspection until its actual observations are recorded.","refs":["bbka-start","ut-records"]},{"id":"beekeeper-06","track":"beekeeper","number":6,"title":"Record worker, queen and drone observations","source":"Mentor’s teaching card: workers perform most colony tasks; the queen is the principal egg-laying female; drones are males. In this paper exercise identify roles from the card, not from unverified photographs.","fields":[{"label":"Principal egg-laying female","answer":"queen","reason":"Use the teaching-card role."},{"label":"Male bees","answer":"drones","reason":"Use the stated category."},{"label":"Most colony tasks","answer":"workers","reason":"Identify workers from the card."}],"method":["Read the three role descriptions.","Match each description to its category.","Record only what the card establishes.","In practical identification ask the mentor rather than claiming certainty."],"example":"Example: a role label describes biology; it is not proof that a queen was seen during today’s inspection.","refs":["arkansas-bees"]},{"id":"beekeeper-07","track":"beekeeper","number":7,"title":"Log brood-stage observations","source":"Mentored record for H-03 states eggs present, larvae present and capped brood present. The queen was not seen. Presence of eggs is an observation; it does not justify recording queen seen.","fields":[{"label":"Colony","answer":"H-03","reason":"Use the inspection’s colony ID."},{"label":"Eggs","answer":"present","reason":"Copy the actual observation."},{"label":"Queen sighting","answer":"not seen","reason":"Do not turn indirect evidence into a sighting."}],"method":["Read each observation separately.","Record eggs, larvae and capped brood as supplied.","Keep queen sighting separate.","Do not diagnose colony status beyond the mentor’s report."],"example":"Example: a record may show eggs present and queen not seen without those entries contradicting each other.","refs":["ut-records","arkansas-bees"]},{"id":"beekeeper-08","track":"beekeeper","number":8,"title":"Record a queen sighting accurately","source":"Inspection I-8: queen seen on frame 4; marking colour not recorded. Exercise rule: unknown details remain not recorded rather than guessed from the year.","fields":[{"label":"Inspection ID","answer":"I-8","reason":"Keep the inspection reference."},{"label":"Frame","answer":"4","reason":"Use the observed frame."},{"label":"Marking colour","answer":"not recorded","reason":"Never invent an unobserved colour."}],"method":["Find the direct sighting entry.","Record frame and inspection reference.","Leave the missing colour explicitly unrecorded.","Ask for clarification if a later task needs that detail."],"example":"Example: queen seen on frame 2 with no marking note does not supply a colour.","refs":["ut-records","arkansas-bees"]},{"id":"beekeeper-09","track":"beekeeper","number":9,"title":"Distinguish observation from diagnosis","source":"H-04 visit note reports unusual brood appearance; no laboratory result or inspector diagnosis exists. Mentor instruction: record concern, seek bee-health advice and do not diagnose from this worksheet.","fields":[{"label":"Colony","answer":"H-04","reason":"Keep the affected colony ID."},{"label":"Diagnosis","answer":"not confirmed","reason":"An observation is not a confirmed disease."},{"label":"Next action","answer":"seek bee-health advice","reason":"Use the prescribed escalation."}],"method":["Copy the observation without a disease label.","Check whether any confirmed diagnosis exists.","Prepare the advice request with colony and visit details.","Do not move material or choose treatment from this paper exercise."],"example":"Example: an unusual appearance triggers expert review, not an invented laboratory finding.","refs":["ut-records","apha-health"]},{"id":"beekeeper-10","track":"beekeeper","number":10,"title":"Compare inspection records","source":"H-05 record A shows 3 frames of brood; record B shows 5. Both use the same counting method. Exercise asks for the numerical change only, not a guarantee of colony health.","fields":[{"label":"Earlier count","answer":"3","reason":"Use record A."},{"label":"Later count","answer":"5","reason":"Use record B."},{"label":"Increase","answer":"2","reason":"5 minus 3 equals 2."}],"method":["Check colony and counting method match.","Copy each visit count with its date reference.","Calculate the difference.","Keep the numerical trend separate from a health diagnosis."],"example":"Example: 4 to 6 measured frames is an increase of 2 under the same method.","refs":["ut-records","arkansas-bees"]},{"id":"beekeeper-11","track":"beekeeper","number":11,"title":"Review a stores observation","source":"Mentor’s fictional H-06 card records stores as low and instructs arrange a mentor review before feeding. No recipe, feeding quantity or medication is authorised.","fields":[{"label":"Colony","answer":"H-06","reason":"Use the named colony."},{"label":"Stores assessment","answer":"low","reason":"This is the mentor’s recorded assessment."},{"label":"Next action","answer":"mentor review before feeding","reason":"Do not invent a feed plan."}],"method":["Record the stores assessment and source.","Check whether a specific feeding plan exists.","Log the review request.","Wait for a locally appropriate mentored plan."],"example":"Example: a low-stores flag is a request for management review, not permission to apply an arbitrary syrup recipe.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-12","track":"beekeeper","number":12,"title":"Record a feeder check","source":"Exercise feeder F-2 on H-07 has a loose cover. Mentor instruction: hold further use and ask the mentor to secure it. No feed quantity was measured.","fields":[{"label":"Feeder ID","answer":"F-2","reason":"Identify the equipment."},{"label":"Condition","answer":"loose cover","reason":"Use the reported fault."},{"label":"Measured feed quantity","answer":"not measured","reason":"Do not make up a measurement."}],"method":["Match feeder and colony.","Record the cover fault.","Flag the equipment for mentor attention.","Leave the unknown quantity unmeasured in the record."],"example":"Example: a damaged feeder is a maintenance observation, not a completed feeding record.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-13","track":"beekeeper","number":13,"title":"Log a swarm concern","source":"At H-08 the mentor reports possible swarm preparations and requests a supervised assessment. No swarm control method has been selected. Exercise next action is supervised assessment, not cutting cells or moving frames independently.","fields":[{"label":"Colony","answer":"H-08","reason":"Use the correct colony reference."},{"label":"Concern status","answer":"possible","reason":"The concern has not been resolved."},{"label":"Next action","answer":"supervised assessment","reason":"Follow the stated plan."}],"method":["Record the concern in the colony history.","Keep possible separate from confirmed outcomes.","Arrange the mentor’s assessment.","Do not log a split or queen intervention that has not occurred."],"example":"Example: suspected swarm preparation remains a review item until the mentor records a management decision.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-14","track":"beekeeper","number":14,"title":"Calculate a monitoring result","source":"Training sample S-9 records 6 mites among 300 sampled adult bees. Calculate mites per 100 bees: mites divided by bees multiplied by 100. This is arithmetic from supplied data, not instructions for sampling or a universal treatment threshold.","fields":[{"label":"Sample ID","answer":"S-9","reason":"Keep the sample traceable."},{"label":"Sampled bees","answer":"300","reason":"Use the denominator supplied."},{"label":"Mites per 100 bees","answer":"2","reason":"6 / 300 × 100 = 2."}],"method":["Identify the sample size and mite count.","Divide 6 by 300.","Multiply by 100 and label the result per 100 bees.","Refer interpretation and locally appropriate action to the mentor."],"example":"Example: 3 mites among 300 bees gives 1 per 100; the result alone does not select a treatment.","refs":["arkansas-bees","ut-records"]},{"id":"beekeeper-15","track":"beekeeper","number":15,"title":"Compare monitoring results carefully","source":"H-09 has result A: 3 mites per 100 bees; result B: 2 per 100. Both use the same method. No action threshold is supplied. Report a decrease of 1 per 100 without declaring the colony clear.","fields":[{"label":"Earlier result","answer":"3","reason":"Use A in the supplied units."},{"label":"Later result","answer":"2","reason":"Use B in the same units."},{"label":"Decrease per 100 bees","answer":"1","reason":"3 minus 2 equals 1."}],"method":["Confirm the method and units are comparable.","Keep each result linked to its visit.","Calculate the difference.","Do not turn a reduction into proof that no mites remain."],"example":"Example: 4 to 3 per 100 decreases by 1; it is not a zero count.","refs":["arkansas-bees","ut-records"]},{"id":"beekeeper-16","track":"beekeeper","number":16,"title":"Prepare a bee-health referral","source":"Referral R-10 concerns H-10 at apiary A-2; visit V-10 recorded abnormal brood. Exercise direction: contact the appropriate bee-health adviser/inspector before moving suspect material.","fields":[{"label":"Referral","answer":"R-10","reason":"Keep the advice request reference."},{"label":"Colony","answer":"H-10","reason":"Identify the affected colony."},{"label":"Movement decision","answer":"hold pending advice","reason":"Do not move suspect material from this exercise."}],"method":["Link referral, colony, apiary and visit.","Copy observations without inventing a diagnosis.","Record the advice request.","Follow the relevant local bee-health authority’s instructions for real cases."],"example":"Example: a concern at K-2 is referred with its own visit record rather than merged with another colony.","refs":["apha-health","arkansas-bees"]},{"id":"beekeeper-17","track":"beekeeper","number":17,"title":"Prepare an inspection appointment record","source":"Exercise appointment AP-4 is for apiary A-3, colonies H-11 and H-12. Arrival time 09:30. It is scheduled, not yet completed.","fields":[{"label":"Appointment","answer":"AP-4","reason":"Use the booking reference."},{"label":"Colonies expected","answer":"2","reason":"H-11 and H-12 are two colonies."},{"label":"Appointment status","answer":"scheduled","reason":"A booking is not a completed inspection."}],"method":["Match the appointment to the site.","List both colony IDs.","Prepare access and records for the agreed visit.","Leave findings blank until the actual inspection."],"example":"Example: a booked visit for three colonies has no results until the inspection happens.","refs":["apha-health","ut-records"]},{"id":"beekeeper-18","track":"beekeeper","number":18,"title":"Check a supplied treatment record","source":"Fictional signed record TR-5 lists H-13, product code P-7 and administrator Mentor M-2. The worksheet contains no dose or authorisation to treat. Copy the record; never infer dosing or use from a product code.","fields":[{"label":"Treatment record","answer":"TR-5","reason":"Keep the signed record ID."},{"label":"Product code","answer":"P-7","reason":"Do not replace it with an invented medicine."},{"label":"Administrator","answer":"Mentor M-2","reason":"Record the person stated on the signed source."}],"method":["Read the existing signed record.","Match colony, product code and administrator.","Flag missing details for the responsible mentor.","For real treatment use local authorisation and the actual product label under appropriate advice."],"example":"Example: copying record TR-2 does not authorise a new treatment or supply a safe dose.","refs":["apha-health","arkansas-bees"]},{"id":"beekeeper-19","track":"beekeeper","number":19,"title":"Review a treatment follow-up","source":"TR-6 has a follow-up monitoring visit booked as V-16. No follow-up result exists. Exercise policy says keep the outcome pending and record V-16 as planned.","fields":[{"label":"Treatment reference","answer":"TR-6","reason":"Link to the original record."},{"label":"Follow-up visit","answer":"V-16","reason":"Use the booked reference."},{"label":"Outcome","answer":"pending","reason":"Do not invent effectiveness before monitoring."}],"method":["Find the treatment record and planned follow-up.","Check whether measurements have actually arrived.","Mark the result pending.","Review the new observations with the mentor when available."],"example":"Example: a scheduled recheck does not itself prove a treatment worked.","refs":["arkansas-bees","ut-records"]},{"id":"beekeeper-20","track":"beekeeper","number":20,"title":"Control shared equipment records","source":"Training equipment tool T-2 was used at a colony with an unresolved health concern. Mentor instruction: isolate and label it for advice. No cleaning agent or procedure is specified.","fields":[{"label":"Tool ID","answer":"T-2","reason":"Identify the affected tool."},{"label":"Current status","answer":"isolated","reason":"Keep it out of shared use."},{"label":"Next action","answer":"seek mentor advice","reason":"Do not invent a chemical treatment."}],"method":["Link the tool to the concern record.","Label it unavailable for shared use.","Record the hold and responsible mentor.","Use the locally approved cleaning procedure only after appropriate advice."],"example":"Example: held tool T-1 is not returned to the shared kit merely because its surface looks clean.","refs":["apha-health","arkansas-bees"]},{"id":"beekeeper-21","track":"beekeeper","number":21,"title":"Prepare a winter-readiness review","source":"Fictional winter checklist for H-14 has 4 items; 3 are verified; stores assessment is outstanding. Mentor review is required before declaring the checklist ready.","fields":[{"label":"Verified items","answer":"3","reason":"Only completed checks count."},{"label":"Outstanding items","answer":"1","reason":"4 minus 3 equals 1."},{"label":"Readiness status","answer":"pending stores review","reason":"Do not mark all four complete."}],"method":["Count verified checklist items.","Name the outstanding stores review.","Arrange the mentor’s assessment.","Keep the checklist pending rather than guessing winter sufficiency."],"example":"Example: 5 of 6 checks completed leaves one unresolved; a checklist is not a guarantee of winter survival.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-22","track":"beekeeper","number":22,"title":"Maintain a seasonal work plan","source":"Mentor plan SP-2 lists spring review, summer monitoring and autumn stores review. It is a local training plan, not a calendar prescribing identical dates everywhere.","fields":[{"label":"Plan ID","answer":"SP-2","reason":"Keep the local plan reference."},{"label":"Summer task","answer":"monitoring","reason":"Read the assigned seasonal task."},{"label":"Autumn task","answer":"stores review","reason":"Use the mentor’s plan."}],"method":["Read the local seasonal plan.","Separate planned tasks from completed visits.","Assign each task to its stated season.","Confirm practical timing with the local mentor and conditions."],"example":"Example: another climate may use different dates; a plan should be reviewed locally rather than copied blindly.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-23","track":"beekeeper","number":23,"title":"Review harvest authorisation","source":"Training harvest card HC-4 covers H-15. Mentor release is pending and a stores review is incomplete. Exercise decision: do not harvest yet. No moisture measurement or food-safety release exists.","fields":[{"label":"Harvest card","answer":"HC-4","reason":"Identify the proposed harvest."},{"label":"Mentor release","answer":"pending","reason":"No release has been given."},{"label":"Decision","answer":"do not harvest yet","reason":"Do not remove stores based on this incomplete card."}],"method":["Check the harvest card and colony.","Look for actual release and stores assessment.","Record missing checks.","Keep harvest pending until the mentor approves an appropriate plan."],"example":"Example: an intended harvest is not a completed or approved extraction batch.","refs":["arkansas-bees","bbka-start"]},{"id":"beekeeper-24","track":"beekeeper","number":24,"title":"Create an extraction batch record","source":"Fictional authorised training batch B-20 comes from H-16 and H-17. Extracted quantity is 18 kg. Record both source colonies; the exercise does not teach extractor operation.","fields":[{"label":"Batch ID","answer":"B-20","reason":"Keep the batch identifier."},{"label":"Source-colony count","answer":"2","reason":"Both colonies must remain traceable."},{"label":"Extracted kg","answer":"18","reason":"Copy the measured amount and unit."}],"method":["Read the signed batch source.","Record both contributing colony IDs.","Copy the quantity with kg units.","Keep batch tracing separate from operating extraction equipment."],"example":"Example: batch B-8 from K-1 and K-2 retains both colony references, not just the first.","refs":["arkansas-bees","ut-records"]},{"id":"beekeeper-25","track":"beekeeper","number":25,"title":"Calculate a packing plan","source":"Training batch B-21 contains 12 kg available for packing. Each jar holds 0.5 kg net honey. Ignore losses for this arithmetic exercise; actual packing requires measured quantities.","fields":[{"label":"Batch ID","answer":"B-21","reason":"Keep the correct batch link."},{"label":"Net kg per jar","answer":"0.5","reason":"Use net honey quantity, not jar weight."},{"label":"Planned jars","answer":"24","reason":"12 divided by 0.5 equals 24."}],"method":["Read batch quantity and jar net amount.","Use consistent kg units.","Divide available quantity by net amount per jar.","Label the result a plan; record actual packing separately."],"example":"Example: 6 kg at 0.5 kg per jar plans 12 jars before any real losses.","refs":["arkansas-bees"]},{"id":"beekeeper-26","track":"beekeeper","number":26,"title":"Separate tare, gross and net weight","source":"Training scale card: full jar gross 750 g; empty container tare 250 g. Net honey equals gross minus tare. This exercise does not certify a scale or legal package compliance.","fields":[{"label":"Gross g","answer":"750","reason":"Gross includes the container."},{"label":"Tare g","answer":"250","reason":"Tare is the empty container."},{"label":"Net g","answer":"500","reason":"750 minus 250 equals 500."}],"method":["Identify gross and tare measurements.","Keep units consistent.","Subtract tare from gross.","Record net contents without treating container mass as honey."],"example":"Example: gross 680 g minus tare 180 g equals net 500 g.","refs":["arkansas-bees"]},{"id":"beekeeper-27","track":"beekeeper","number":27,"title":"Review a training jar label","source":"Fictional label brief LB-3 requires product name Honey, batch B-22 and net 500 g. It does not provide every label element required in any real jurisdiction. Check this brief, then seek local food-labelling guidance for real sales.","fields":[{"label":"Product name","answer":"Honey","reason":"Copy the product from the brief."},{"label":"Batch","answer":"B-22","reason":"Preserve traceability."},{"label":"Net grams","answer":"500","reason":"Use the net quantity, not gross jar mass."}],"method":["Compare the draft with the supplied label brief.","Check the batch against the packing record.","Check net quantity and units.","Do not claim full legal compliance from these three fields."],"example":"Example: a training label for B-9 with net 250 g must match that batch’s record.","refs":["arkansas-bees"]},{"id":"beekeeper-28","track":"beekeeper","number":28,"title":"Reconcile jars and breakages","source":"B-23 packing log: 30 jars prepared, 2 broken before filling, 28 filled. Broken containers are excluded from available packing stock. The exercise authorises no salvage of contaminated honey.","fields":[{"label":"Prepared jars","answer":"30","reason":"Use the initial count."},{"label":"Broken jars","answer":"2","reason":"Record the loss separately."},{"label":"Filled jars","answer":"28","reason":"30 minus 2 equals 28."}],"method":["Compare prepared, lost and filled counts.","Record the breakage separately.","Reconcile the remaining count.","Escalate any contamination concern using the real food-safety procedure."],"example":"Example: 20 containers minus 1 damaged container leaves 19 available, not 20 saleable jars.","refs":["arkansas-bees"]},{"id":"beekeeper-29","track":"beekeeper","number":29,"title":"Trace a batch distribution","source":"Fictional B-24 has 24 jars: 10 to Welcome House, 8 to the Fair and 6 retained. A quality concern requires holding the retained jars and notifying the responsible batch lead; no real recall is being initiated.","fields":[{"label":"Distributed jars","answer":"18","reason":"10 plus 8 equals 18."},{"label":"Retained jars","answer":"6","reason":"Use the retained stock count."},{"label":"Total traced jars","answer":"24","reason":"18 plus 6 equals 24."}],"method":["Link each destination to B-24.","Add distributed and retained quantities.","Check the total reconciles to the batch.","Prepare a recipient list for the responsible lead rather than contacting real people."],"example":"Example: 12 jars split as 5, 4 and 3 reconcile to 12 and preserve all destinations.","refs":["arkansas-bees","ut-records"]},{"id":"beekeeper-30","track":"beekeeper","number":30,"title":"Write the season handover","source":"Fictional season SH-1 records 6 colonies, 5 completed final reviews and 1 pending mentor review. Final handover must preserve the unresolved review, not declare all colonies healthy.","fields":[{"label":"Season record","answer":"SH-1","reason":"Use the season’s reference."},{"label":"Completed reviews","answer":"5","reason":"Count only recorded completed reviews."},{"label":"Pending reviews","answer":"1","reason":"6 minus 5 equals 1."}],"method":["Reconcile the colony register with review records.","Count completed and outstanding visits.","List the pending mentor action in the handover.","Retain colony histories for the next season; do not infer health from paperwork completeness."],"example":"Example: a handover with 4 of 5 reviews complete clearly names the remaining review.","refs":["ut-records","arkansas-bees"]}]};if(typeof module==="object"&&module.exports)module.exports=d;else r.HoneybrookSpecialistData=d;})(globalThis);
